CREATE TABLE IF NOT EXISTS loos(id TEXT PRIMARY KEY,name TEXT NOT NULL,category TEXT NOT NULL,lat REAL NOT NULL,lon REAL NOT NULL,address TEXT,access_mode TEXT NOT NULL,fee_pence INTEGER,fee_note TEXT,accessible INTEGER,baby_change INTEGER,changing_places INTEGER,radar INTEGER,opening_hours_json TEXT,hours_note TEXT,location_note TEXT,confidence TEXT NOT NULL DEFAULT 'curated',active INTEGER NOT NULL DEFAULT 1,last_verified TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);CREATE TABLE IF NOT EXISTS sources(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,url TEXT NOT NULL,source_type TEXT NOT NULL,checked_at TEXT);CREATE TABLE IF NOT EXISTS loo_sources(loo_id TEXT NOT NULL,source_id INTEGER NOT NULL,PRIMARY KEY(loo_id,source_id),FOREIGN KEY(loo_id) REFERENCES loos(id),FOREIGN KEY(source_id) REFERENCES sources(id));CREATE TABLE IF NOT EXISTS reviews(id INTEGER PRIMARY KEY AUTOINCREMENT,loo_id TEXT NOT NULL,access_confirmed INTEGER,open_confirmed INTEGER,cleanliness INTEGER,queue_level TEXT,accessible_confirmed INTEGER,baby_change_confirmed INTEGER,comment TEXT,moderation_status TEXT NOT NULL DEFAULT 'pending',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(loo_id) REFERENCES loos(id));CREATE TABLE IF NOT EXISTS submissions(id INTEGER PRIMARY KEY AUTOINCREMENT,proposed_name TEXT NOT NULL,lat REAL,lon REAL,address TEXT,source_url TEXT,notes TEXT,moderation_status TEXT NOT NULL DEFAULT 'pending',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);CREATE INDEX IF NOT EXISTS idx_loos_active ON loos(active);CREATE INDEX IF NOT EXISTS idx_loos_lat_lon ON loos(lat,lon);CREATE INDEX IF NOT EXISTS idx_reviews_loo ON reviews(loo_id,moderation_status);CREATE INDEX IF NOT EXISTS idx_submissions_status ON submissions(moderation_status);